import numpy as np
from scipy.optimize import minimize

N = 26
CANDIDATE_SAMPLES = 5000

def construct_packing() -> tuple:
    np.random.seed(123)
    # --- Stage 1: Greedy Constructive Heuristic for Seeding ---
    greedy_centers = []
    greedy_radii = []

    for i in range(N):
        best_candidate_center = None
        max_radius = -1.0
        candidate_points = np.random.rand(CANDIDATE_SAMPLES, 2)

        for point in candidate_points:
            r_bound = min(point[0], 1.0 - point[0], point[1], 1.0 - point[1])
            current_max_r = r_bound

            for c_idx in range(len(greedy_centers)):
                dist = np.linalg.norm(point - greedy_centers[c_idx])
                max_r_from_circle = dist - greedy_radii[c_idx]
                current_max_r = min(current_max_r, max_r_from_circle)

            current_max_r = max(0, current_max_r)

            if current_max_r > max_radius:
                max_radius = current_max_r
                best_candidate_center = point

        if best_candidate_center is not None:
            greedy_centers.append(best_candidate_center)
            greedy_radii.append(max_radius)
        else:
            greedy_centers.append(np.random.rand(2))
            greedy_radii.append(1e-6)

    greedy_centers = np.array(greedy_centers)
    greedy_radii = np.array(greedy_radii)

    # --- Stage 2: SLSQP Refinement ---
    def cr_to_z(c, r): return np.concatenate([c.flatten(), r])
    def z_to_cr(z): return z[:N*2].reshape(N, 2), z[N*2:]
    def objective(z): return -np.sum(z[N*2:])
    def ineq_boundary(z):
        c, r = z_to_cr(z)
        return np.concatenate([c[:,0] - r, 1 - (c[:,0] + r), c[:,1] - r, 1 - (c[:,1] + r)])
    def ineq_nonoverlap(z):
        c, r = z_to_cr(z)
        diff = c[:, None, :] - c[None, :, :]; dist = np.sqrt(np.sum(diff**2, axis=-1))
        iu = np.triu_indices(N, 1); return dist[iu] - (r[iu[0]] + r[iu[1]])
    def _ensure_validity(c, r):
        for _ in range(10):
            v=0
            for i in range(N):
                for j in range(i + 1, N):
                    dist = np.linalg.norm(c[i] - c[j]); rad_sum = r[i] + r[j]
                    if dist < rad_sum: v+=1; scale = (dist/rad_sum)*(1.0-1e-9); r[i]*=scale; r[j]*=scale
            if v==0: break
        r_vec = r.reshape(-1, 1); c = np.clip(c, r_vec, 1.0 - r_vec)
        return c, np.maximum(r, 1e-6)

    initial_z = cr_to_z(greedy_centers, greedy_radii)
    bounds = [(0,1)]*N*2 + [(1e-6, 0.5)]*N
    constraints = [{'type': 'ineq', 'fun': ineq_boundary}, {'type': 'ineq', 'fun': ineq_nonoverlap}]

    res = minimize(objective, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 2000, 'ftol': 1e-10})

    if res.success:
        c_res, r_res = z_to_cr(res.x)
        return _ensure_validity(c_res, r_res)
    else:
        return _ensure_validity(greedy_centers, greedy_radii)
